-- FastAPI owns authorization; browser roles have no direct table access.

CREATE TABLE users (
	id SERIAL NOT NULL,
	member_id VARCHAR(20),
	name VARCHAR(120) NOT NULL,
	email VARCHAR(180),
	password_hash VARCHAR(255) NOT NULL,
	must_change_password BOOLEAN NOT NULL,
	email_verified BOOLEAN NOT NULL,
	phone_verified BOOLEAN NOT NULL,
	role VARCHAR(9) NOT NULL,
	phone VARCHAR(30),
	location VARCHAR(120),
	status VARCHAR(9) NOT NULL,
	face_encoding TEXT,
	id_image_url VARCHAR(300),
	avatar_url VARCHAR(300),
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
	updated_at TIMESTAMP WITH TIME ZONE,
	PRIMARY KEY (id),
	CONSTRAINT user_role CHECK (role IN ('member', 'librarian')),
	CONSTRAINT user_status CHECK (status IN ('active', 'suspended'))
);

CREATE UNIQUE INDEX ix_users_email ON users (email);

CREATE INDEX ix_users_id ON users (id);

CREATE UNIQUE INDEX ix_users_member_id ON users (member_id);

CREATE TABLE books (
	id SERIAL NOT NULL,
	title VARCHAR(255) NOT NULL,
	author VARCHAR(180) NOT NULL,
	category VARCHAR(80) NOT NULL,
	year INTEGER,
	isbn VARCHAR(20),
	copies_total INTEGER NOT NULL,
	copies_available INTEGER NOT NULL,
	location_shelf VARCHAR(80),
	cover_url VARCHAR(500),
	qr_code VARCHAR(30),
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
	updated_at TIMESTAMP WITH TIME ZONE,
	PRIMARY KEY (id),
	UNIQUE (isbn)
);

CREATE INDEX ix_books_title ON books (title);

CREATE UNIQUE INDEX ix_books_qr_code ON books (qr_code);

CREATE INDEX ix_books_category ON books (category);

CREATE INDEX ix_books_id ON books (id);

CREATE TABLE library_settings (
	key VARCHAR(80) NOT NULL,
	value VARCHAR(255) NOT NULL,
	PRIMARY KEY (key)
);

CREATE TABLE book_copies (
	id SERIAL NOT NULL,
	book_id INTEGER NOT NULL,
	copy_number INTEGER NOT NULL,
	qr_code VARCHAR(40) NOT NULL,
	status VARCHAR(9) NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
	updated_at TIMESTAMP WITH TIME ZONE,
	PRIMARY KEY (id),
	CONSTRAINT uq_book_copy_number UNIQUE (book_id, copy_number),
	FOREIGN KEY(book_id) REFERENCES books (id),
	CONSTRAINT book_copy_status CHECK (status IN ('available', 'borrowed', 'damaged', 'lost', 'retired'))
);

CREATE UNIQUE INDEX ix_book_copies_qr_code ON book_copies (qr_code);

CREATE INDEX ix_book_copies_book_id ON book_copies (book_id);

CREATE INDEX ix_book_copies_id ON book_copies (id);

CREATE TABLE reservations (
	id SERIAL NOT NULL,
	user_id INTEGER NOT NULL,
	book_id INTEGER NOT NULL,
	status VARCHAR(9) NOT NULL,
	queue_position INTEGER,
	reserved_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
	expires_at TIMESTAMP WITH TIME ZONE,
	PRIMARY KEY (id),
	FOREIGN KEY(user_id) REFERENCES users (id),
	FOREIGN KEY(book_id) REFERENCES books (id),
	CONSTRAINT reservation_status CHECK (status IN ('pending', 'ready', 'cancelled', 'fulfilled'))
);

CREATE INDEX ix_reservations_id ON reservations (id);

CREATE TABLE entry_logs (
	id SERIAL NOT NULL,
	user_id INTEGER,
	entry_type VARCHAR(9) NOT NULL,
	granted BOOLEAN NOT NULL,
	note VARCHAR(255),
	accessed_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
	time_out TIMESTAMP WITH TIME ZONE,
	PRIMARY KEY (id),
	FOREIGN KEY(user_id) REFERENCES users (id),
	CONSTRAINT entry_type CHECK (entry_type IN ('face_scan', 'manual'))
);

CREATE INDEX ix_entry_logs_id ON entry_logs (id);

CREATE TABLE face_embeddings (
	id SERIAL NOT NULL,
	user_id INTEGER NOT NULL,
	engine VARCHAR(40) NOT NULL,
	dimension INTEGER NOT NULL,
	embedding TEXT NOT NULL,
	quality_score FLOAT,
	source VARCHAR(40) NOT NULL,
	is_active BOOLEAN NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
	PRIMARY KEY (id),
	FOREIGN KEY(user_id) REFERENCES users (id)
);

CREATE INDEX ix_face_embeddings_engine ON face_embeddings (engine);

CREATE INDEX ix_face_embeddings_user_id ON face_embeddings (user_id);

CREATE INDEX ix_face_embeddings_is_active ON face_embeddings (is_active);

CREATE INDEX ix_face_embeddings_id ON face_embeddings (id);

CREATE TABLE reading_goals (
	id SERIAL NOT NULL,
	user_id INTEGER NOT NULL,
	goal_type VARCHAR(50) NOT NULL,
	target INTEGER NOT NULL,
	current INTEGER NOT NULL,
	year INTEGER NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
	updated_at TIMESTAMP WITH TIME ZONE,
	PRIMARY KEY (id),
	FOREIGN KEY(user_id) REFERENCES users (id)
);

CREATE INDEX ix_reading_goals_id ON reading_goals (id);

CREATE TABLE password_reset_codes (
	id SERIAL NOT NULL,
	user_id INTEGER NOT NULL,
	channel VARCHAR(5) NOT NULL,
	code_hash VARCHAR(128) NOT NULL,
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
	used_at TIMESTAMP WITH TIME ZONE,
	created_at TIMESTAMP WITH TIME ZONE NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(user_id) REFERENCES users (id),
	CONSTRAINT password_reset_channel CHECK (channel IN ('email', 'sms'))
);

CREATE INDEX ix_password_reset_codes_id ON password_reset_codes (id);

CREATE INDEX ix_password_reset_codes_code_hash ON password_reset_codes (code_hash);

CREATE INDEX ix_password_reset_codes_user_id ON password_reset_codes (user_id);

CREATE TABLE security_alerts (
	id SERIAL NOT NULL,
	alert_type VARCHAR(32) NOT NULL,
	user_id INTEGER,
	ip_address VARCHAR(64),
	snapshot_b64 TEXT,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
	is_read BOOLEAN NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(user_id) REFERENCES users (id)
);

CREATE INDEX ix_security_alerts_id ON security_alerts (id);

CREATE TABLE transactions (
	id SERIAL NOT NULL,
	user_id INTEGER NOT NULL,
	book_id INTEGER NOT NULL,
	copy_id INTEGER,
	type VARCHAR(6) NOT NULL,
	borrow_date TIMESTAMP WITH TIME ZONE DEFAULT now(),
	due_date TIMESTAMP WITH TIME ZONE,
	return_date TIMESTAMP WITH TIME ZONE,
	fine_amount NUMERIC(8, 2),
	status VARCHAR(8) NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
	PRIMARY KEY (id),
	FOREIGN KEY(user_id) REFERENCES users (id),
	FOREIGN KEY(book_id) REFERENCES books (id),
	FOREIGN KEY(copy_id) REFERENCES book_copies (id),
	CONSTRAINT transaction_type CHECK (type IN ('borrow', 'return')),
	CONSTRAINT transaction_status CHECK (status IN ('active', 'returned', 'overdue'))
);

CREATE INDEX ix_transactions_copy_id ON transactions (copy_id);

CREATE INDEX ix_transactions_id ON transactions (id);

CREATE TABLE notifications (
	id SERIAL NOT NULL,
	user_id INTEGER,
	message VARCHAR(255) NOT NULL,
	type VARCHAR(50) NOT NULL,
	member_name VARCHAR(100),
	book_title VARCHAR(200),
	reservation_id INTEGER,
	is_read BOOLEAN NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE,
	PRIMARY KEY (id),
	FOREIGN KEY(user_id) REFERENCES users (id),
	FOREIGN KEY(reservation_id) REFERENCES reservations (id)
);

CREATE INDEX ix_notifications_id ON notifications (id);

